function validate([loginTime, logoutTime]) {
  for (const t of [loginTime, logoutTime]) {
    if (typeof t !== 'string' || !/^\d\d:\d\d$/.test(t)) return 'Times must look like "hh:mm".';
    if (Number(t.slice(0, 2)) > 23) return 'Hours go from 00 to 23.';
    if (Number(t.slice(3)) > 59) return 'Minutes go from 00 to 59.';
  }
  if (loginTime === logoutTime) return 'loginTime and logoutTime must differ.';
  return null;
}

