function numberOfRounds(loginTime, logoutTime) {
  const start = Number(loginTime.slice(0, 2)) * 60 + Number(loginTime.slice(3));
  let end = Number(logoutTime.slice(0, 2)) * 60 + Number(logoutTime.slice(3));
  if (end < start) {
    end += 24 * 60;
  }
  const firstRound = Math.ceil(start / 15);
  const lastRound = Math.floor(end / 15);
  return Math.max(0, lastRound - firstRound);
}

