function numberOfRounds(loginTime, logoutTime) {
  const [h1, m1] = loginTime.split(':').map(Number);
  const [h2, m2] = logoutTime.split(':').map(Number);
  const login = h1 * 60 + m1;
  const logout = h2 * 60 + m2 + (h2 * 60 + m2 < login ? 1440 : 0);
  // Walk over every round of today and tomorrow and test whether it fits inside the session.
  let count = 0;
  for (let begin = 0; begin < 2 * 1440; begin += 15) {
    if (begin >= login && begin + 15 <= logout) count++;
  }
  return count;
}

