function generate(rand, size) {
  const pad = (v) => String(v).padStart(2, '0');
  // Times land on a quarter hour or right next to one often, as those are the interesting edges.
  const minute = () => {
    const pick = rand();
    if (pick < 0.25) return 15 * Math.floor(rand() * 4);
    if (pick < 0.5) return Math.min(59, 15 * Math.floor(rand() * 4) + (rand() < 0.5 ? 1 : 14));
    return Math.floor(rand() * 60);
  };
  const time = () => pad(Math.floor(rand() * 24)) + ':' + pad(minute());
  const loginTime = time();
  let logoutTime = time();
  // A short session within the same hour shows the case where no round fits.
  if (size === 'small' && rand() < 0.2) logoutTime = loginTime.slice(0, 3) + pad(Math.floor(rand() * 60));
  while (logoutTime === loginTime) logoutTime = time();
  return [loginTime, logoutTime];
}
